const TARGET_PATH = "../../../src/core/lib/ConvertCoordinates.mjs";
const ERROR_PATH = "../../../src/core/errors/OperationError.mjs";

let convertCoordinates;
let findDirs;
let findFormat;
let findDelim;
let realDelim;
let FORMATS;
let OperationError;

beforeAll(() => {
    return import(TARGET_PATH)
        .then(module => {
            ({
                convertCoordinates,
                findDirs,
                findFormat,
                findDelim,
                realDelim,
                FORMATS
            } = module);
            return import(ERROR_PATH);
        })
        .then(module => {
            OperationError = module.default;
        });
});

function expectOperationError(fn, expectedMessage) {
    let error;
    try {
        fn();
    } catch (caught) {
        error = caught;
    }

    expect(error).toBeInstanceOf(OperationError);
    expect(error.type).toBe("OperationError");
    expect(error.message).toBe(expectedMessage);
}

describe("public exports", () => {
    test("exposes the supported coordinate formats in display order", () => {
        expect(FORMATS).toEqual([
            "Degrees Minutes Seconds",
            "Degrees Decimal Minutes",
            "Decimal Degrees",
            "Geohash",
            "Military Grid Reference System",
            "Ordnance Survey National Grid",
            "Universal Transverse Mercator"
        ]);
    });

    test("exposes the conversion and parsing helpers", () => {
        expect(convertCoordinates).toEqual(expect.any(Function));
        expect(findDirs).toEqual(expect.any(Function));
        expect(findFormat).toEqual(expect.any(Function));
        expect(findDelim).toEqual(expect.any(Function));
        expect(realDelim).toEqual(expect.any(Function));
    });
});

describe("realDelim", () => {
    test.each([
        ["Auto", "Auto"],
        ["Space", " "],
        ["\\n", "\n"],
        ["Comma", ","],
        ["Semi-colon", ";"],
        ["Colon", ":"]
    ])("maps the %s delimiter name to %p", (name, expected) => {
        expect(realDelim(name)).toBe(expected);
    });

    test("returns undefined for an unknown delimiter name", () => {
        expect(realDelim("Pipe")).toBeUndefined();
    });
});

describe("findDelim", () => {
    test.each([
        ["51.5074, -0.1278", ","],
        ["51.5074; -0.1278", ";"],
        ["51:30:26", ":"],
        ["  51.5074, -0.1278  ", ","]
    ])("detects the delimiter used in %p", (input, expected) => {
        expect(findDelim(input)).toBe(expected);
    });

    test("detects a compass direction before each coordinate", () => {
        expect(findDelim("N 51.5074, W 0.1278")).toBe("Direction Preceding");
    });

    test("detects a compass direction after each coordinate", () => {
        expect(findDelim("51.5074 N, 0.1278 W")).toBe("Direction Following");
    });

    test("returns null when no supported delimiter can be found", () => {
        expect(findDelim("51.5074 -0.1278")).toBeNull();
    });

    test("does not accept more than two coordinate fields", () => {
        expect(findDelim("1,2,3,4")).toBeNull();
    });
});

describe("findDirs", () => {
    test("uses explicit compass directions and normalizes their case", () => {
        expect(findDirs("33.8688 s, 151.2093 e", ",")).toEqual(["S", "E"]);
    });

    test("infers latitude and longitude directions from signed values", () => {
        expect(findDirs("51.5074, -0.1278", ",")).toEqual(["N", "W"]);
    });

    test("returns an empty longitude direction when only one coordinate is present", () => {
        expect(findDirs("-33.8688", ",")).toEqual(["S", ""]);
    });

    test("supports direction-aware input delimiters", () => {
        expect(findDirs("S 33.8688 E 151.2093", "Direction Preceding")).toEqual(["S", "E"]);
    });
});

describe("findFormat", () => {
    test.each([
        ["51.5074, -0.1278", ",", "Decimal Degrees"],
        ["51.5074", ",", "Decimal Degrees"],
        ["51 30.444 N, 0 7.668 W", ",", "Degrees Decimal Minutes"],
        ["51° 30' 26.64\" N, 0° 7' 40.08\" W", ",", "Degrees Minutes Seconds"],
        ["gcpvj0duq0", ",", "Geohash"],
        ["30 N 699319.6208 5708878.3041", ",", "Universal Transverse Mercator"],
        ["30U XC 99319 08878", ",", "Military Grid Reference System"],
        ["TQ 31979 79606", ",", "Ordnance Survey National Grid"]
    ])("detects %p with delimiter %p as %s", (input, delim, expected) => {
        expect(findFormat(input, delim)).toBe(expected);
    });

    test("detects DMS input when the delimiter is a compass direction", () => {
        expect(findFormat("51 30 26 N, 0 7 40 W", "Direction Following"))
            .toBe("Degrees Minutes Seconds");
    });

    test("returns null for unrecognized input", () => {
        expect(findFormat("not a coordinate", ",")).toBeNull();
    });
});

