describe("convertCoordinates automatic detection and boundaries", () => {
    test("automatically detects a comma delimiter and Decimal Degrees input", () => {
        expect(convertCoordinates(
            "51.5074, -0.1278",
            "Auto",
            "Auto",
            "Degrees Decimal Minutes",
            "Comma",
            "None",
            3
        )).toBe("51° 30.444',-0° 7.668',");
    });

    test("automatically detects compass directions and their position", () => {
        expect(convertCoordinates(
            "51.5074 N, 0.1278 W",
            "Auto",
            "Auto",
            "Decimal Degrees",
            "Comma",
            "After",
            4
        )).toBe("51.5074° N,0.1278° W,");
    });

    test("automatically detects a semicolon input and translates a colon output", () => {
        expect(convertCoordinates(
            "51.5074; -0.1278",
            "Auto",
            "Auto",
            "Decimal Degrees",
            "Colon",
            "None",
            4
        )).toBe("51.5074°:-0.1278°:");
    });

    test("clamps negative precision to zero", () => {
        expect(convertCoordinates(
            "51.5074, -0.1278",
            "Decimal Degrees",
            "Comma",
            "Decimal Degrees",
            "Comma",
            "None",
            -3
        )).toBe("52°,0°,");
    });

    test("handles a single coordinate without creating a longitude value", () => {
        expect(convertCoordinates(
            "-33.8688",
            "Decimal Degrees",
            "Comma",
            "Degrees Minutes Seconds",
            "Comma",
            "After",
            2
        )).toBe("33° 52' 7.68\" S,");
    });

    test("throws when an automatic input delimiter cannot be detected", () => {
        expectOperationError(
            () => convertCoordinates(
                "51.5074 -0.1278",
                "Decimal Degrees",
                "Auto",
                "Decimal Degrees",
                "Comma",
                "None",
                4
            ),
            "Unable to detect the input delimiter automatically."
        );
    });

    test("throws when an automatic input format cannot be detected", () => {
        expectOperationError(
            () => convertCoordinates(
                "not a coordinate,really",
                "Auto",
                "Comma",
                "Decimal Degrees",
                "Comma",
                "None",
                4
            ),
            "Unable to detect the input format automatically."
        );
    });
});

describe("convertCoordinates errors", () => {
    test("throws for an unknown input format", () => {
        expectOperationError(
            () => convertCoordinates(
                "51.5074,-0.1278",
                "Mystery",
                "Comma",
                "Decimal Degrees",
                "Comma",
                "None",
                4
            ),
            "Unknown input format 'Mystery'"
        );
    });

    test("throws when the output format produces no converted value", () => {
        expectOperationError(
            () => convertCoordinates(
                "51.5074,-0.1278",
                "Decimal Degrees",
                "Comma",
                "Mystery",
                "Comma",
                "None",
                4
            ),
            "Error converting co-ordinates."
        );
    });

    test.each([
        [
            "Degrees Minutes Seconds",
            "51 30, 0 6",
            "Invalid co-ordinate format for Degrees Minutes Seconds"
        ],
        [
            "Degrees Decimal Minutes",
            "51 30 0, 0 6 0",
            "Invalid co-ordinate format for Degrees Decimal Minutes."
        ],
        [
            "Decimal Degrees",
            "51 30, 0 6",
            "Invalid co-ordinate format for Decimal Degrees."
        ]
    ])("rejects malformed %s input", (format, input, message) => {
        expectOperationError(
            () => convertCoordinates(input, format, "Comma", "Decimal Degrees", "Comma", "None", 4),
            message
        );
    });

    test.each([
        [
            "Degrees Minutes Seconds",
            "51 30",
            "Invalid co-ordinate format for Degrees Minutes Seconds"
        ],
        [
            "Degrees Decimal Minutes",
            "51 30 0",
            "Invalid co-ordinate format for Degrees Decimal Minutes."
        ],
        [
            "Decimal Degrees",
            "51 30",
            "Invalid co-ordinate format for Decimal Degrees."
        ]
    ])("rejects a malformed single %s value", (format, input, message) => {
        expectOperationError(
            () => convertCoordinates(input, format, "Comma", "Decimal Degrees", "Comma", "None", 4),
            message
        );
    });

    test("throws when coordinates fall outside the Ordnance Survey grid", () => {
        expectOperationError(
            () => convertCoordinates(
                "10, 10",
                "Decimal Degrees",
                "Comma",
                "Ordnance Survey National Grid",
                "Comma",
                "None",
                4
            ),
            "Could not convert co-ordinates to OS National Grid. Are the co-ordinates in range?"
        );
    });
});

